//  checked.hpp
//  snicholls-core
//
//  Copyright 2010-2026 Saxon Herschel Nicholls
//

/// \file
/// \brief Checked and saturating integer arithmetic, `numeric_cast` that refuses a lossy conversion, and `parse_number`.
/// \ingroup core
///
/// **Overview.** A money path must not wrap silently. `checked_add`, `checked_sub` and `checked_mul` return
/// `std::nullopt` instead of overflowing; `saturating_*` clamp to the type's range; `numeric_cast<To>` gives
/// `std::nullopt` unless the value survives the conversion exactly; `parse_number<T>` reads a whole string
/// with `std::from_chars` and returns the reason it could not. Integers use the compiler's overflow builtins,
/// one instruction and a flag, and a portable form during constant evaluation and on MSVC.
///
/// \snippet checked_demo.cpp checked
///
/// **Relationships.** `uint256.hpp` for 256-bit amounts, which checks the same way; `result.hpp`; 
/// `meta/assignable.hpp` for refusing narrowing at compile time. Group: \ref core.
///
/// **Guarantees.** `constexpr` and `noexcept`, but `parse_number`, which is `noexcept` and not `constexpr`
/// for floating point.
///
/// **Errors.** `std::nullopt`, or a `std::errc` in the `result`: `invalid_argument` for text that is not a
/// number or has trailing characters, `result_out_of_range` for one that does not fit.
///
/// **Performance.** Not benchmarked: a builtin and a branch.
///
/// **Tests and demos.** `tests/checked_test.cpp`, `demos/checked_demo.cpp`.
///
/// **Dependencies.** `<algorithm>`, `<array>`, `<cerrno>`, `<charconv>`, `<cstdlib>`, `<concepts>`, `<limits>`, `<optional>`, `<string_view>`, `<system_error>`,
/// `<type_traits>`, `<utility>`, `result.hpp`.
///
/// **Known issues.** Integers only for the arithmetic; floating point has its own infinities. Where the standard
/// library lacks floating-point `std::from_chars` (Xcode 16's libc++ and older), `parse_number` of a floating-point
/// type uses the C library: the same syntax, but the decimal point follows `LC_NUMERIC` if the program changes it,
/// and text over 255 characters is refused.
///
/// **Status.** New in 0.5.0.

#ifndef snicholls_core_checked_hpp
#define snicholls_core_checked_hpp


#include <algorithm>
#include <array>
#include <cerrno>
#include <charconv>
#include <cstdlib>
#include <concepts>
#include <limits>
#include <optional>
#include <string_view>
#include <system_error>
#include <type_traits>
#include <utility>

namespace snicholls {

    /// \brief `a + b`, or none if it overflows `T`.
    /// \ingroup core
    /// \tparam T An integer type.
    /// \param a One.
    /// \param b The other.
    /// \return The sum.
    template <std::integral T>
    [[nodiscard]] constexpr std::optional<T> checked_add(T a, T b) noexcept
    {
#if defined(__GNUC__) || defined(__clang__)
        T r{};
        if (!__builtin_add_overflow(a, b, &r))
            return r;
        return std::nullopt;
#else
        if (b > 0 ? a > std::numeric_limits<T>::max() - b : a < std::numeric_limits<T>::min() - b)
            return std::nullopt;
        return static_cast<T>(a + b);
#endif
    }

    /// \brief `a - b`, or none if it overflows `T`.
    /// \ingroup core
    /// \tparam T An integer type.
    /// \param a One.
    /// \param b The other.
    /// \return The difference.
    template <std::integral T>
    [[nodiscard]] constexpr std::optional<T> checked_sub(T a, T b) noexcept
    {
#if defined(__GNUC__) || defined(__clang__)
        T r{};
        if (!__builtin_sub_overflow(a, b, &r))
            return r;
        return std::nullopt;
#else
        if (b > 0 ? a < std::numeric_limits<T>::min() + b : a > std::numeric_limits<T>::max() + b)
            return std::nullopt;
        return static_cast<T>(a - b);
#endif
    }

    /// \brief `a * b`, or none if it overflows `T`.
    /// \ingroup core
    /// \tparam T An integer type.
    /// \param a One.
    /// \param b The other.
    /// \return The product.
    template <std::integral T>
    [[nodiscard]] constexpr std::optional<T> checked_mul(T a, T b) noexcept
    {
#if defined(__GNUC__) || defined(__clang__)
        T r{};
        if (!__builtin_mul_overflow(a, b, &r))
            return r;
        return std::nullopt;
#else
        if (a == 0 || b == 0)
            return T{0};
        // min * -1 first: the division below would itself overflow on it
        if (std::is_signed_v<T> && ((a == T(-1) && b == std::numeric_limits<T>::min()) || (b == T(-1) && a == std::numeric_limits<T>::min())))
            return std::nullopt;
        const T r = static_cast<T>(static_cast<std::make_unsigned_t<T>>(a) * static_cast<std::make_unsigned_t<T>>(b));
        if (r / b != a)
            return std::nullopt;
        return r;
#endif
    }

    /// \brief `a + b`, clamped to `T`'s range.
    /// \ingroup core
    /// \tparam T An integer type.
    /// \param a One.
    /// \param b The other.
    /// \return The sum, or the bound it passed.
    template <std::integral T>
    [[nodiscard]] constexpr T saturating_add(T a, T b) noexcept
    {
        return checked_add(a, b).value_or(b > 0 ? std::numeric_limits<T>::max() : std::numeric_limits<T>::min());
    }

    /// \brief `a - b`, clamped to `T`'s range.
    /// \ingroup core
    /// \tparam T An integer type.
    /// \param a One.
    /// \param b The other.
    /// \return The difference, or the bound it passed.
    template <std::integral T>
    [[nodiscard]] constexpr T saturating_sub(T a, T b) noexcept
    {
        return checked_sub(a, b).value_or(b < 0 ? std::numeric_limits<T>::max() : std::numeric_limits<T>::min());
    }

    /// \brief `a * b`, clamped to `T`'s range.
    /// \ingroup core
    /// \tparam T An integer type.
    /// \param a One.
    /// \param b The other.
    /// \return The product, or the bound it passed.
    template <std::integral T>
    [[nodiscard]] constexpr T saturating_mul(T a, T b) noexcept
    {
        return checked_mul(a, b).value_or((a < 0) != (b < 0) ? std::numeric_limits<T>::min() : std::numeric_limits<T>::max());
    }

    /// \brief The value as a `To`, or none if the conversion would change it: out of range, or a fraction lost.
    /// \ingroup core
    /// \tparam To   The target arithmetic type.
    /// \tparam From The source arithmetic type.
    /// \param v The value.
    /// \return It, converted exactly.
    template <typename To, typename From>
        requires std::is_arithmetic_v<To> && std::is_arithmetic_v<From>
    [[nodiscard]] constexpr std::optional<To> numeric_cast(From v) noexcept
    {
        if constexpr (std::integral<To> && std::integral<From>) {
            return std::in_range<To>(v) ? std::optional<To>(static_cast<To>(v)) : std::nullopt;
        } else {
            if (v != v)   // NaN survives only into a floating type
                return std::floating_point<To> ? std::optional<To>(static_cast<To>(v)) : std::nullopt;
            if (std::integral<To> && (v < static_cast<From>(std::numeric_limits<To>::lowest()) ||
                                      v >= static_cast<From>(std::numeric_limits<To>::max()) + static_cast<From>(1)))
                return std::nullopt;
            const To t = static_cast<To>(v);
            return static_cast<From>(t) == v ? std::optional<To>(t) : std::nullopt;
        }
    }

    namespace detail::parse {
        // Whether the standard library converts T with std::from_chars: every one does integers; Xcode 16's libc++
        // and older have no floating-point overloads (a double would reach the deleted bool overload).
        template <typename T>
        concept has_from_chars = requires(const char* p, T& v) {
            { std::from_chars(p, p, v) } -> std::same_as<std::from_chars_result>;
        };

        // The text std::from_chars accepts for a floating-point number in its general format: an optional minus, then
        // digits with an optional point and exponent, or inf, infinity, nan, nan(chars), in any case. No leading
        // space, no plus, no hexadecimal.
        constexpr bool float_syntax(std::string_view t) noexcept
        {
            const auto lower = [](char c) { return static_cast<char>(c >= 'A' && c <= 'Z' ? c - 'A' + 'a' : c); };
            const auto starts = [&](std::string_view w) {
                if (t.size() < w.size())
                    return false;
                for (std::size_t i = 0; i < w.size(); ++i)
                    if (lower(t[i]) != w[i])
                        return false;
                return true;
            };
            const auto digit = [](char c) { return c >= '0' && c <= '9'; };
            if (!t.empty() && t.front() == '-')
                t.remove_prefix(1);
            if (starts("infinity"))
                return t.size() == 8;
            if (starts("inf"))
                return t.size() == 3;
            if (starts("nan")) {
                t.remove_prefix(3);
                if (t.empty())
                    return true;
                if (t.front() != '(' || t.back() != ')')
                    return false;
                for (const char c : t.substr(1, t.size() - 2))
                    if (!(digit(c) || (lower(c) >= 'a' && lower(c) <= 'z') || c == '_'))
                        return false;
                return true;
            }
            std::size_t i = 0, mantissa = 0;
            while (i < t.size() && digit(t[i]))
                ++i, ++mantissa;
            if (i < t.size() && t[i] == '.') {
                ++i;
                while (i < t.size() && digit(t[i]))
                    ++i, ++mantissa;
            }
            if (mantissa == 0)
                return false;
            if (i < t.size() && (t[i] == 'e' || t[i] == 'E')) {
                ++i;
                if (i < t.size() && (t[i] == '+' || t[i] == '-'))
                    ++i;
                const std::size_t exponent = i;
                while (i < t.size() && digit(t[i]))
                    ++i;
                if (i == exponent)
                    return false;
            }
            return i == t.size();
        }

        inline float c_parse(const char* b, char** e, float*) noexcept { return std::strtof(b, e); }
        inline double c_parse(const char* b, char** e, double*) noexcept { return std::strtod(b, e); }
        inline long double c_parse(const char* b, char** e, long double*) noexcept { return std::strtold(b, e); }

        // The fallback where std::from_chars has no floating-point overload: the same syntax, checked first, then the
        // C library's correctly rounded conversion. The C library reads the decimal point from LC_NUMERIC, which is
        // "." unless the program calls setlocale; up to 255 characters.
        template <std::floating_point T>
        result<T, std::errc> parse_float(std::string_view text) noexcept
        {
            if (!float_syntax(text) || text.size() > 255)
                return err(std::errc::invalid_argument);
            std::array<char, 256> buffer{};
            std::copy(text.begin(), text.end(), buffer.begin());
            char* end = nullptr;
            errno = 0;
            const T value = c_parse(buffer.data(), &end, static_cast<T*>(nullptr));
            if (end != buffer.data() + text.size())
                return err(std::errc::invalid_argument);
            if (errno == ERANGE && (value > T(1) || value < T(-1)))   // overflow; an underflow is the nearest value
                return err(std::errc::result_out_of_range);
            return ok(value);
        }
    } // namespace detail::parse

    /// \brief A whole string as a number, by `std::from_chars`: no leading space, no trailing characters.
    /// \ingroup core
    ///
    /// Where the standard library has no floating-point `std::from_chars` (Xcode 16's libc++ and older), a floating-point
    /// type is parsed with the same syntax by the C library instead; see Known issues.
    /// \tparam T An integer or floating-point type.
    /// \param text The text.
    /// \return The number, or `std::errc::invalid_argument` / `std::errc::result_out_of_range`.
    template <typename T>
        requires std::is_arithmetic_v<T> && (!std::same_as<T, bool>) && detail::parse::has_from_chars<T>
    [[nodiscard]] result<T, std::errc> parse_number(std::string_view text) noexcept
    {
        T value{};
        const auto [end, ec] = std::from_chars(text.data(), text.data() + text.size(), value);
        if (ec != std::errc{})
            return err(ec);
        if (end != text.data() + text.size())
            return err(std::errc::invalid_argument);
        return ok(value);
    }

    /// \brief A whole string as a floating-point number where `std::from_chars` cannot parse one: the same syntax, by the C library.
    /// \ingroup core
    /// \tparam T A floating-point type.
    /// \param text The text.
    /// \return The number, or `std::errc::invalid_argument` / `std::errc::result_out_of_range`.
    template <std::floating_point T>
        requires(!detail::parse::has_from_chars<T>)
    [[nodiscard]] result<T, std::errc> parse_number(std::string_view text) noexcept
    {
        return detail::parse::parse_float<T>(text);
    }

} // namespace snicholls

#endif /* snicholls_core_checked_hpp */
//
//  constexpr_for.hpp
//  snicholls-core
//
//  Copyright 2010-2026 Saxon Herschel Nicholls
//
//  Moved from ts-moveables (TSMoveables/utils/constexpr_for.hpp at d7e0f10).
//  The definitions are unchanged; the guard and documentation are core's.
//

/// \file
/// \brief `constexpr_for`, `constexpr_nest`, `unrolled_for`: compile-time loop unrolling.
/// \ingroup core
///
/// **Overview.** `constexpr_for<Start, End, Inc>` expands into exactly the calls it
/// needs and leaves no loop at all: the bounds are template parameters, so there is
/// no counter, no compare and no branch. The body is handed
/// `std::integral_constant<T, I>`, not a bare `T`, so `I.value` is a constant
/// expression inside the body and can index a tuple or be a template argument,
/// while `I` still converts to its value for ordinary arithmetic:
///
/// \snippet constexpr_for_demo.cpp tuple
///
/// `constexpr_nest<E0, E1, ...>` unrolls nested loops to any depth, row-major, with
/// a constant index per level. `unrolled_for<Unroll>(first, last, body)` walks a
/// *run-time* range with the body emitted `Unroll` times per iteration and a tail.
///
/// **Relationships.** For iterating *values* (an index range, a tuple-like by
/// index). To operate on a pack of *types*, use `type_list` (CLAUDE.md "Idioms").
///
/// **Guarantees.** Expansion is a fold over an `index_sequence`, depth 1 whatever
/// the count, so there is no instantiation-depth cliff. The iteration count is
/// computed in `long long`, so a negative step against unsigned bounds cannot wrap.
/// A step of 0 is a compile error. Trailing arguments reach every call as lvalues,
/// never forwarded, so a body cannot move from the same object twice.
///
/// **Performance.** At -O2 compilers already unroll simple counted loops, and doing
/// it by hand can lose. Reach for `constexpr_for` when the body must be instantiated
/// per index; reach for `unrolled_for` only with a benchmark in hand. Not
/// benchmarked in core; ts-moveables' `make bench-parallel` compares them.
///
/// **Tests and demos.** `tests/constexpr_for_test.cpp`, `demos/constexpr_for_demo.cpp`.
///
/// **Dependencies.** `<cstddef>`, `<type_traits>`, `<utility>`.
///
/// **Known issues.** `constexpr_nest<8, 8, 8>` is 512 copies of the body: for small
/// fixed extents, not whole arrays.
///
/// **Status.** Stable.

// Implementation notes, as written in ts-moveables:
//
//      constexpr_for<0, 4>      ([&](auto I) { use<I.value>(); });   // fully unrolled
//      constexpr_for<0, 10, 2>  ([&](auto I) { even(I); });          // with a step
//      constexpr_for<10, 0, -1> ([&](auto I) { down(I); });          // and backwards
//      constexpr_for<0, 3>      (f, a, b);                           // f(I, a, b)
//      unrolled_for<4>(0, n, [&](std::size_t i) { out[i] = g(in[i]); });
//
//  constexpr_for<Start, End, Inc> expands into exactly the calls it needs and
//  leaves no loop at all - the bounds are template parameters, so there is no
//  counter, no compare and no branch. unrolled_for takes a RUN-TIME range and
//  emits the body Unroll times per iteration, with a tail for the remainder.
//
//  ------------------------------------------------------ the index is a type
//
//  The body is handed std::integral_constant<T, I>, not a bare T, and that is
//  the whole reason this is worth having over a plain loop.
//
//  A function parameter is never a constant expression, however constant the
//  value passed in was - so a body taking `std::size_t i` cannot write
//  std::get<i>(tuple) or use i as a template argument, which is usually the
//  entire point of unrolling by hand. Handing it a type carrying the index
//  fixes that: `I.value` is a constant expression inside the body, while `I`
//  still converts implicitly to its underlying type, so the ordinary
//  arithmetic spelling keeps working:
//
//      constexpr_for<0, N>([&](auto I) { sum += v[I]; });                // fine
//      constexpr_for<0, N>([&](auto I) { use(std::get<I.value>(tup)); }); // also fine
//
//  The index type is decltype(Start), so constexpr_for<0, 4> yields int and
//  constexpr_for<std::size_t{0}, std::size_t{4}> yields std::size_t. Say which
//  you want when it matters.
//
//  ------------------------------------------------------------ expansion, not
//                                                                  recursion
//  The obvious implementation recurses - body, then constexpr_for<Start+Inc,
//  End, Inc> - and it is shorter. This expands an index_sequence through a fold
//  instead, because the recursive form instantiates one template per iteration:
//  template depth grows with the count, a few hundred iterations meets the
//  compiler's instantiation-depth limit, and compile time grows superlinearly
//  well before that. The fold is depth 1 whatever the count. Same unrolled
//  output, no cliff to fall off.
//
//  ------------------------------------------------------------ extra arguments
//
//  Trailing arguments are passed through to every call as LVALUES, never
//  forwarded. Forwarding would move the same object once per iteration, which
//  is a use-after-move that compiles quietly; if a body needs to consume
//  something it should capture it instead.
//
//  ------------------------------------------------------------- when to reach
//
//  Be sceptical of unrolled_for as a speed tool. At -O2 the compiler already
//  unrolls simple counted loops, and doing it by hand can lose: more code in
//  the instruction cache, more live registers, and a tail that confuses the
//  vectoriser. `make bench-parallel` prints unrolled against not so the claim
//  stays falsifiable rather than folkloric.
//
//  Where it does earn its place: when the body must be instantiated per index -
//  a tuple element, a template argument, a fixed-size matrix row - which no
//  compiler unroll can do for you, because that is a language requirement
//  rather than an optimisation. Reach for constexpr_for for that; reach for
//  unrolled_for only with a benchmark in hand.
//

#ifndef snicholls_core_constexpr_for_hpp
#define snicholls_core_constexpr_for_hpp

#include <cstddef>
#include <type_traits>
#include <utility>

namespace snicholls
{
    namespace detail
    {
        // How many iterations [Start, End) by Inc actually performs. Computed
        // in long long so a negative Inc against unsigned bounds cannot wrap -
        // the arithmetic that makes a hand-rolled version of this silently
        // produce 18 quintillion iterations.
        constexpr std::size_t constexpr_for_count(long long start, long long end, long long inc)
        {
            const long long span = (inc > 0) ? (end - start) : (start - end);
            const long long step = (inc > 0) ? inc : -inc;
            return span > 0 ? static_cast<std::size_t>((span + step - 1) / step) : 0u;
        }

        template <auto Start, auto Inc, typename F, std::size_t... I, typename... Args>
        constexpr void constexpr_for_impl(F&& f, std::index_sequence<I...>, Args&... args)
        {
            using T = decltype(Start);
            // Fold over the comma operator: one call per index, in order, and
            // nothing at all generated for an empty sequence.
            (static_cast<void>(f(std::integral_constant<
                                     T, static_cast<T>(static_cast<long long>(Start) +
                                                       static_cast<long long>(I) *
                                                           static_cast<long long>(Inc))>{},
                                 args...)),
             ...);
        }
    } // namespace detail

    /// \brief Call `f(I, args...)` for each `I` in [Start, End) stepping by `Inc`, fully unrolled.
    /// \tparam Start The first index; its type is the index type.
    /// \tparam End   The open end of the range.
    /// \tparam Inc   The step; negative counts down; 0 is a compile error.
    /// \tparam F     The body: callable with `std::integral_constant<decltype(Start), I>`, then `args...`.
    /// \tparam Args  Trailing argument types.
    /// \param f      The body.
    /// \param args   Passed to every call as lvalues.
    // Invoke f(I, args...) for each I in [Start, End) stepping by Inc, fully
    // unrolled at compile time. Inc may be negative to count down. I is an
    // integral_constant<decltype(Start), ...>.
    template <auto Start, auto End, auto Inc = 1, typename F, typename... Args>
    constexpr void constexpr_for(F&& f, Args&&... args)
    {
        static_assert(Inc != 0, "constexpr_for with a step of 0 would never terminate");
        constexpr std::size_t n = detail::constexpr_for_count(
            static_cast<long long>(Start), static_cast<long long>(End),
            static_cast<long long>(Inc));
        detail::constexpr_for_impl<Start, Inc>(std::forward<F>(f),
                                               std::make_index_sequence<n>{}, args...);
    }

    /// \brief Call `f(I, args...)` for each `I` in [0, Count), fully unrolled.
    /// \tparam Count The number of iterations; its type is the index type.
    /// \tparam F     The body.
    /// \tparam Args  Trailing argument types.
    /// \param f      The body.
    /// \param args   Passed to every call as lvalues.
    // Invoke f(I, args...) for each I in [0, Count) - the common case, shorter.
    // Disjoint from the overload above: that one cannot deduce End, this one
    // cannot take a second non-type argument.
    template <auto Count, typename F, typename... Args>
    constexpr void constexpr_for(F&& f, Args&&... args)
    {
        constexpr_for<static_cast<decltype(Count)>(0), Count, 1>(std::forward<F>(f), args...);
    }

    namespace detail
    {
        // N-deep nest, peeled one extent at a time. The recursion here is over
        // DEPTH (2, 3, 4...), not over iteration count, so it is three or four
        // instantiations deep rather than thousands - the cliff the flat
        // constexpr_for avoids by folding does not exist on this axis.
        template <std::size_t... Extents>
        struct nest;

        template <>
        struct nest<> {
            template <typename F, typename... Acc>
            static constexpr void run(F& f, Acc... acc) { f(acc...); }
        };

        template <std::size_t E0, std::size_t... Rest>
        struct nest<E0, Rest...> {
            template <typename F, typename... Acc>
            static constexpr void run(F& f, Acc... acc)
            {
                constexpr_for<std::size_t{0}, E0>(
                    [&](auto I) { nest<Rest...>::run(f, acc..., I); });
            }
        };
    } // namespace detail

    /// \brief Nested loops, every level unrolled: `f(I, J, ...)` for every point, row-major.
    /// \tparam Extents The extent of each level, outermost first.
    /// \tparam F       The body: one `integral_constant<std::size_t, ...>` per level.
    /// \param f        The body.
    // Nested loops, every level unrolled, to any depth:
    //
    //     constexpr_nest<2, 3>   ([&](auto I, auto J)         { m[I][J] += a[I]*b[J]; });
    //     constexpr_nest<2, 3, 4>([&](auto I, auto J, auto K) { t[I][J][K] = 0; });
    //
    // The body is called once per point of the cartesian product, in row-major
    // order (last extent varies fastest), with one integral_constant per level
    // - so every index is a constant expression and a fixed-size kernel can be
    // written with no loop and no run-time indexing at all.
    //
    // Mind the multiplication: <8,8,8> is 512 expansions of the body, and the
    // object code grows with it. This is for small fixed extents - a 4x4
    // transform, a tile of a matrix kernel - not for whole arrays.
    template <std::size_t... Extents, typename F>
    constexpr void constexpr_nest(F&& f)
    {
        detail::nest<Extents...>::run(f);
    }

    /// \brief Walk a run-time range [first, last), calling `body(i, args...)`, unrolled `Unroll` times with a tail.
    /// \tparam Unroll Copies of the body per iteration, at least 1.
    /// \tparam Index  An integral index type.
    /// \tparam Body   Callable with `(Index, Args&...)`.
    /// \tparam Args   Trailing argument types.
    /// \param first   The first index.
    /// \param last    The open end; an inverted range does nothing.
    /// \param body    The body.
    /// \param args    Passed to every call as lvalues.
    // Walk a RUN-TIME range [first, last), calling body(i, args...) for each i,
    // with the body emitted Unroll times per iteration and a tail loop for the
    // remainder.
    //
    // body receives a plain Index here, not an integral_constant: the value is
    // genuinely a run-time one, and pretending otherwise would be a lie that
    // only compiles when the bounds happen to be constant.
    template <std::size_t Unroll = 4, typename Index, typename Body, typename... Args>
    constexpr void unrolled_for(Index first, Index last, Body body, Args&... args)
    {
        static_assert(std::is_integral_v<Index>, "unrolled_for needs an integral index");
        static_assert(Unroll >= 1, "unrolled_for needs an unroll factor of at least 1");

        if (!(first < last))
            return;

        const auto count = static_cast<std::size_t>(last - first);
        const auto whole = count - (count % Unroll);
        const Index main_end = first + static_cast<Index>(whole);

        Index i = first;
        for (; i < main_end; i += static_cast<Index>(Unroll))
            constexpr_for<std::size_t{0}, Unroll>(
                [&](auto K) { body(i + static_cast<Index>(K.value), args...); });
        for (; i < last; ++i)                       // the tail Unroll did not divide
            body(i, args...);
    }
} // namespace snicholls

#endif /* snicholls_core_constexpr_for_hpp */
//
//  constexpr_map.hpp
//  snicholls-core
//
//  Copyright 2010-2026 Saxon Herschel Nicholls
//
//  The shape is the same, an aggregate over std::array<std::pair<Key, Value>, N>; core adds contains,
//  find_key, keys_unique, iteration, a factory and a throwing at.
//

/// \file
/// \brief `snicholls::constexpr_map`: a fixed table of key-value pairs, looked up at compile time or run time.
/// \ingroup core
///
/// **Overview.** A map whose contents are known when the program is written: an enumeration's
/// names, a protocol's codes, a unit's scale factors. It is an aggregate over a
/// `std::array` of pairs, so it is a literal type: declare it `constexpr`, look it up in a
/// `static_assert` or a `case` label, and nothing is built at run time:
///
/// \snippet constexpr_map_demo.cpp table
///
/// Lookups are linear, which for the tables this is for (tens of entries) beats a hash or a
/// tree at compile time and at run time. `find` returns a pointer or null; `at` throws, which
/// in a constant expression is a compile error; `find_key` looks the other way, for the
/// enumeration-to-name-and-back pair of tables that would otherwise be two.
///
/// **Relationships.** `snicholls::fixed_string` makes a compile-time key; `basic_type_registry`
/// binds names to types where the value is a type rather than a value. Group: \ref core.
///
/// **Guarantees.** An aggregate and a literal type: `constexpr` construction and every lookup
/// when `Key` and `Value` are literal types with a `constexpr operator==`. `find`,
/// `find_key`, `contains` and `keys_unique` are `noexcept`. No allocation, no run-time
/// initialisation. Keys need not be unique; `find` returns the first match, and
/// `keys_unique()` says whether that matters.
///
/// **Errors.** `at` throws `std::out_of_range` when the key is absent, at run time; in a
/// constant expression the throw makes the expression not constant, so the program does not
/// compile.
///
/// **Performance.** O(N) comparisons per lookup. Not benchmarked: a table of tens of entries
/// compared by `==` is a handful of instructions, and a constant-expression lookup is none.
///
/// **Tests and demos.** `tests/constexpr_map_test.cpp`, `demos/constexpr_map_demo.cpp`.
///
/// **Dependencies.** `<array>`, `<cstddef>`, `<stdexcept>`, `<utility>`.
///
/// **Known issues.** A key type with no `constexpr operator==` (a `std::string`) still works
/// at run time but not in a constant expression; use `std::string_view` or
/// `snicholls::fixed_string` for text keys.
///
/// **Status.** New in 0.5.0.

#ifndef snicholls_core_constexpr_map_hpp
#define snicholls_core_constexpr_map_hpp

#include <array>
#include <cstddef>
#include <stdexcept>
#include <utility>

namespace snicholls {

    /// \brief A fixed table of `N` key-value pairs, an aggregate over `std::array`, looked up by linear search.
    /// \ingroup core
    /// \tparam Key   The key type; needs `operator==`.
    /// \tparam Value The value type; `find_key` needs its `operator==`.
    /// \tparam N     The number of entries.
    template <typename Key, typename Value, std::size_t N>
    struct constexpr_map {
        /// \brief The key type.
        using key_type = Key;
        /// \brief The value type.
        using mapped_type = Value;
        /// \brief One entry.
        using value_type = std::pair<Key, Value>;
        /// \brief The iterator over entries.
        using const_iterator = typename std::array<value_type, N>::const_iterator;

        /// \brief The entries, in the order written.
        std::array<value_type, N> entries;

        /// \brief The number of entries.
        /// \return `N`.
        [[nodiscard]] static constexpr std::size_t size() noexcept { return N; }

        /// \brief Whether there are no entries.
        /// \return `N == 0`.
        [[nodiscard]] static constexpr bool empty() noexcept { return N == 0; }

        /// \brief The value for `key`, or null.
        /// \param key The key.
        /// \return A pointer to the first entry's value whose key equals `key`, or null.
        [[nodiscard]] constexpr const Value* find(const Key& key) const noexcept
        {
            for (const auto& entry : entries)
                if (entry.first == key)
                    return &entry.second;
            return nullptr;
        }

        /// \brief The key for `value`, or null: the reverse lookup.
        /// \param value The value.
        /// \return A pointer to the first entry's key whose value equals `value`, or null.
        [[nodiscard]] constexpr const Key* find_key(const Value& value) const noexcept
        {
            for (const auto& entry : entries)
                if (entry.second == value)
                    return &entry.first;
            return nullptr;
        }

        /// \brief Whether some entry has this key.
        /// \param key The key.
        /// \return true when `find(key)` is not null.
        [[nodiscard]] constexpr bool contains(const Key& key) const noexcept { return find(key) != nullptr; }

        /// \brief The value for `key`.
        /// \param key The key.
        /// \return The first entry's value whose key equals `key`.
        /// \throws std::out_of_range when no entry has the key; in a constant expression, a compile error.
        [[nodiscard]] constexpr const Value& at(const Key& key) const
        {
            if (const Value* found = find(key))
                return *found;
            throw std::out_of_range("snicholls::constexpr_map::at: key not found");
        }

        /// \brief Whether every key appears once.
        /// \return true when no two entries share a key.
        [[nodiscard]] constexpr bool keys_unique() const noexcept
        {
            for (std::size_t i = 0; i < N; ++i)
                for (std::size_t j = i + 1; j < N; ++j)
                    if (entries[i].first == entries[j].first)
                        return false;
            return true;
        }

        /// \brief The first entry.
        /// \return An iterator to it.
        [[nodiscard]] constexpr const_iterator begin() const noexcept { return entries.begin(); }

        /// \brief One past the last entry.
        /// \return An iterator to it.
        [[nodiscard]] constexpr const_iterator end() const noexcept { return entries.end(); }
    };

    /// \brief Deduction guide: `constexpr_map{std::array{std::pair{k, v}, ...}}`.
    /// \tparam Key   The key type.
    /// \tparam Value The value type.
    /// \tparam N     The number of entries.
    template <typename Key, typename Value, std::size_t N>
    constexpr_map(std::array<std::pair<Key, Value>, N>) -> constexpr_map<Key, Value, N>;

    /// \brief Build a `constexpr_map` from its pairs: `make_constexpr_map(std::pair{k1, v1}, std::pair{k2, v2})`.
    /// \ingroup core
    /// \tparam Key   The key type, from the first pair.
    /// \tparam Value The value type, from the first pair.
    /// \tparam Rest  The remaining pairs, each convertible to `std::pair<Key, Value>`.
    /// \param first The first entry.
    /// \param rest  The other entries, in order.
    /// \return The map.
    template <typename Key, typename Value, typename... Rest>
    [[nodiscard]] constexpr constexpr_map<Key, Value, 1 + sizeof...(Rest)> make_constexpr_map(std::pair<Key, Value> first,
                                                                                            Rest... rest)
    {
        return constexpr_map<Key, Value, 1 + sizeof...(Rest)>{
            std::array<std::pair<Key, Value>, 1 + sizeof...(Rest)>{std::move(first), std::pair<Key, Value>(std::move(rest))...}};
    }
}

#endif /* snicholls_core_constexpr_map_hpp */
