namespace snicholls {

/// \brief A digest's hexadecimal text: `2 * Bytes` lowercase digits and a `'\0'`, held by value.
/// \ingroup core
///
/// There is no implicit conversion to `std::string_view`: `std::string_view v = d.hex();` would view a temporary
/// that is gone at the semicolon. Keep the text (`auto text = d.hex();`) and take `text.view()`.
/// \tparam Bytes The digest's length in bytes.
template <std::size_t Bytes>
struct digest_hex
{
    /// \brief The digits and the terminator. Public for aggregate use; read it through `view()`.
    char chars[2 * Bytes + 1]{};

    /// \brief The digits.
    /// \return A view of the `2 * Bytes` digits.
    [[nodiscard]] constexpr std::string_view view() const noexcept { return {chars, 2 * Bytes}; }
    /// \brief The digits as a C string.
    /// \return A pointer to the null-terminated digits.
    [[nodiscard]] constexpr const char* c_str() const noexcept { return chars; }
    /// \brief The number of digits.
    /// \return `2 * Bytes`.
    [[nodiscard]] static constexpr std::size_t size() noexcept { return 2 * Bytes; }
};

/// \brief `N` bytes produced by a hash: compared, ordered, printed and parsed as hexadecimal, all `constexpr`.
/// \ingroup core
///
/// An aggregate: `digest<4>{}` is four zero bytes, `digest<4>{{std::byte{1}, ...}}` names them. The bytes are in
/// the order the algorithm's specification writes them, which is the order of the hexadecimal.
/// \tparam N The length in bytes.
template <std::size_t N>
struct digest
{
    /// \brief The bytes. Public, so a digest is structural and an aggregate.
    std::array<std::byte, N> bytes{};

    /// \brief The length in bytes.
    /// \return `N`.
    [[nodiscard]] static constexpr std::size_t size() noexcept { return N; }
    /// \brief The first byte.
    /// \return A pointer to the bytes.
    [[nodiscard]] constexpr const std::byte* data() const noexcept { return bytes.data(); }
    /// \brief The first byte, writable.
    /// \return A pointer to the bytes.
    [[nodiscard]] constexpr std::byte* data() noexcept { return bytes.data(); }
    /// \brief Iteration over the bytes.
    /// \return An iterator to the first byte.
    [[nodiscard]] constexpr auto begin() const noexcept { return bytes.begin(); }
    /// \brief Iteration over the bytes.
    /// \return An iterator past the last byte.
    [[nodiscard]] constexpr auto end() const noexcept { return bytes.end(); }
    /// \brief One byte.
    /// \param i The index, `< N`.
    /// \return The byte.
    [[nodiscard]] constexpr std::byte operator[](std::size_t i) const noexcept { return bytes[i]; }
    /// \brief One byte, writable.
    /// \param i The index, `< N`.
    /// \return The byte.
    [[nodiscard]] constexpr std::byte& operator[](std::size_t i) noexcept { return bytes[i]; }
    /// \brief The bytes as a fixed-extent span.
    /// \return A span of the `N` bytes.
    [[nodiscard]] constexpr std::span<const std::byte, N> span() const noexcept { return std::span<const std::byte, N>(bytes); }

    /// \brief The lowercase hexadecimal of the bytes, `2N` digits, without allocating.
    /// \return The text, by value.
    [[nodiscard]] constexpr digest_hex<N> hex() const noexcept
    {
        constexpr char digits[] = "0123456789abcdef";
        digest_hex<N> out{};
        for (std::size_t i = 0; i < N; ++i) {
            const auto b = static_cast<unsigned>(bytes[i]);
            out.chars[2 * i] = digits[b >> 4];
            out.chars[2 * i + 1] = digits[b & 0xFu];
        }
        return out;
    }

    /// \brief The first `M` bytes, as a digest of their own (a truncated hash, an Ethereum address from Keccak-256).
    /// \tparam M The length kept, `<= N`.
    /// \return The prefix.
    template <std::size_t M>
        requires(M <= N)
    [[nodiscard]] constexpr digest<M> first() const noexcept
    {
        digest<M> out{};
        for (std::size_t i = 0; i < M; ++i)
            out.bytes[i] = bytes[i];
        return out;
    }

    /// \brief The digest written as hexadecimal: exactly `2N` digits of either case, after an optional `0x` or `0X`.
    /// \param text The text.
    /// \return The digest, or `std::nullopt` for any other text.
    [[nodiscard]] static constexpr std::optional<digest> from_hex(std::string_view text) noexcept
    {
        if (text.size() >= 2 && text[0] == '0' && (text[1] == 'x' || text[1] == 'X'))
            text.remove_prefix(2);
        if (text.size() != 2 * N)
            return std::nullopt;
        digest out{};
        for (std::size_t i = 0; i < N; ++i) {
            const int hi = nibble(text[2 * i]), lo = nibble(text[2 * i + 1]);
            if (hi < 0 || lo < 0)
                return std::nullopt;
            out.bytes[i] = static_cast<std::byte>((hi << 4) | lo);
        }
        return out;
    }

    /// \brief Equality of every byte. Not constant-time: use `constant_time_equal` for a secret.
    /// \return Whether the bytes are equal.
    friend constexpr bool operator==(const digest&, const digest&) noexcept = default;
    /// \brief Lexicographic order of the bytes, for sorted containers.
    /// \return The ordering.
    friend constexpr std::strong_ordering operator<=>(const digest& a, const digest& b) noexcept
    {
        for (std::size_t i = 0; i < N; ++i)
            if (a.bytes[i] != b.bytes[i])
                return static_cast<unsigned>(a.bytes[i]) <=> static_cast<unsigned>(b.bytes[i]);
        return std::strong_ordering::equal;
    }

    /// \brief Writes the lowercase hexadecimal: how `acout`, `print` and `print_to` show a digest.
    /// \param os The stream.
    void print(std::ostream& os) const { os << hex().view(); }

private:
    static constexpr int nibble(char c) noexcept
    {
        return c >= '0' && c <= '9' ? c - '0' : c >= 'a' && c <= 'f' ? c - 'a' + 10 : c >= 'A' && c <= 'F' ? c - 'A' + 10 : -1;
    }
};

/// \brief Whether `T` is a `digest<N>`.
/// \ingroup core
template <typename T>
inline constexpr bool is_digest_v = false;

/// \brief A `digest<N>` is a digest.
/// \ingroup core
template <std::size_t N>
inline constexpr bool is_digest_v<digest<N>> = true;

/// \brief What a hash accepts: a sequence of one-byte code units under core's string rules, or a `digest<N>`.
/// \ingroup core
///
/// `std::string`, `std::string_view`, a string literal (length N - 1), `const char*`, `char8_t` text,
/// `std::span<const std::byte>`, `std::vector<std::uint8_t>`, `std::array<std::byte, N>`, a `digest<N>`.
/// Not wider text, whose bytes depend on the host's byte order.
template <typename S>
concept hash_input = (code_unit_sequence<S> && sizeof(code_unit_t<S>) == 1) || is_digest_v<std::remove_cvref_t<S>>;

namespace detail {

    // The code units and length of a hash_input, without copying: the string_access rules for sequences, the
    // bytes for a digest. Overloads, not a chain of if constexpr.
    template <typename S>
        requires(code_unit_sequence<S> && sizeof(code_unit_t<S>) == 1)
    constexpr const code_unit_t<S>* input_data(const S& s) noexcept
    {
        return data_of(s);
    }
    template <typename S>
        requires(code_unit_sequence<S> && sizeof(code_unit_t<S>) == 1)
    constexpr std::size_t input_size(const S& s) noexcept
    {
        return length_of(s);
    }
    template <std::size_t N>
    constexpr const std::byte* input_data(const digest<N>& d) noexcept
    {
        return d.bytes.data();
    }
    template <std::size_t N>
    constexpr std::size_t input_size(const digest<N>&) noexcept
    {
        return N;
    }

    // update(input) for every hasher, forwarding the units to Derived::absorb(const U*, std::size_t).
    template <typename Derived>
    class hash_updates
    {
    public:
        template <hash_input S>
        constexpr Derived& update(const S& input) noexcept
        {
            Derived& self = static_cast<Derived&>(*this);
            self.absorb(input_data(input), input_size(input));
            return self;
        }
    };

    // hash(input): one-shot, for a hasher that is default-constructible; update(input) through hash_updates. One chain
    // of empty bases, not two side by side: MSVC gives only the first of several empty bases no size.
    template <typename Derived>
    class one_shot_hash : public hash_updates<Derived>
    {
    public:
        template <hash_input S>
        [[nodiscard]] static constexpr auto hash(const S& input) noexcept
        {
            Derived h;
            h.update(input);
            return h.finish();
        }
    };

} // namespace detail

/// \brief A fixed-length hash: incremental `update` / `finish`, a one-shot `hash`, `block_size` and `digest_size`.
/// \ingroup core
///
/// SHA-1, every SHA-2 and SHA-3, Keccak-256, RIPEMD-160, BLAKE2b, BLAKE2s and BLAKE3 meet it; `hmac<H>`,
/// `hkdf_extract<H>`, `hkdf_expand<H>` and `pbkdf2_hmac<H>` take any `H` that does.
template <typename H>
concept hash_function = std::default_initializable<H> && std::copyable<H> && requires(H h, std::string_view s) {
    { H::block_size } -> std::convertible_to<std::size_t>;
    { H::digest_size } -> std::convertible_to<std::size_t>;
    h.update(s);
    { h.finish() } -> std::same_as<digest<H::digest_size>>;
};

/// \brief The digest a hash function returns: `digest<H::digest_size>`.
/// \ingroup core
template <hash_function H>
using digest_of_t = digest<H::digest_size>;

/// \brief A Merkle-Damgard hash over a policy: the class behind `sha1`, every SHA-2 and `ripemd160`.
/// \ingroup core
///
/// Use it through its aliases. `update(input)` absorbs any `hash_input` and returns the hasher, so calls chain;
/// `finish()` pads, compresses the last block and returns the digest; `hash(input)` is both at once.
/// \tparam Policy The algorithm (internal).
template <typename Policy>
class md_hash : public detail::one_shot_hash<md_hash<Policy>>
{
public:
    /// \brief The block size in bytes (64 or 128): what `hmac` pads the key to.
    static constexpr std::size_t block_size = Policy::block_size;
    /// \brief The digest size in bytes.
    static constexpr std::size_t digest_size = Policy::digest_size;
    /// \brief The digest type.
    using digest_type = digest<digest_size>;

    /// \brief A hasher with nothing absorbed.
    constexpr md_hash() noexcept = default;

    /// \brief Pads, compresses the last block and returns the digest. The hasher is not used afterwards.
    /// \return The digest.
    [[nodiscard]] constexpr digest_type finish() noexcept
    {
        digest_type out{};
        engine_.finish(out.bytes.data());
        return out;
    }

private:
    friend detail::hash_updates<md_hash>;
    template <typename U>
    constexpr void absorb(const U* p, std::size_t n) noexcept
    {
        engine_.absorb(p, n);
    }

    detail::md_engine<Policy> engine_{};
};

} // namespace snicholls

#endif /* snicholls_core_hash_digest_hpp */

#include <cstddef>
#include <span>
#include <type_traits>

namespace snicholls {

/// \brief Zeroes `s` in a way the optimiser may not remove, for memory that held a secret.
/// \ingroup core
/// \tparam T A trivially copyable element type (bytes, words, a `digest<N>`).
/// \tparam Extent The span's extent.
/// \param s The memory.
template <typename T, std::size_t Extent>
    requires(std::is_trivially_copyable_v<T> && !std::is_const_v<T>)
constexpr void secure_wipe(std::span<T, Extent> s) noexcept
{
    if (std::is_constant_evaluated()) {
        for (T& x : s)
            x = T{};
        return;
    }
    if (!s.empty())
        detail::volatile_zero(static_cast<void*>(s.data()), s.size_bytes());
}

/// \brief Zeroes a digest (a derived key, a MAC) in a way the optimiser may not remove.
/// \ingroup core
/// \param d The digest.
template <std::size_t N>
constexpr void secure_wipe(digest<N>& d) noexcept
{
    secure_wipe(std::span<std::byte, N>(d.bytes));
}

/// \brief Whether `a` and `b` hold the same bytes, in time independent of where they differ.
/// \ingroup core
/// \param a One sequence (any `hash_input`: bytes, text, a digest).
/// \param b The other.
/// \return `true` when the lengths and every byte are equal.
template <hash_input A, hash_input B>
[[nodiscard]] constexpr bool constant_time_equal(const A& a, const B& b) noexcept
{
    const std::size_t n = detail::input_size(a);
    if (n != detail::input_size(b))
        return false;
    const auto* pa = detail::input_data(a);
    const auto* pb = detail::input_data(b);
    unsigned difference = 0;
    for (std::size_t i = 0; i < n; ++i)
        difference |= static_cast<unsigned>(detail::octet_of(pa[i]) ^ detail::octet_of(pb[i]));
    if (std::is_constant_evaluated())
        return difference == 0;
    return detail::volatile_is_zero(difference);
}

} // namespace snicholls

#endif /* snicholls_core_hash_secure_hpp */

#include <algorithm>
#include <cstddef>
#include <ostream>
#include <span>
#include <string>
#include <string_view>
#include <type_traits>
#include <utility>

namespace snicholls {

/// \brief The masked text.
inline constexpr std::string_view masked_text = "********";

/// \brief Secrets: values that must never be printed or logged.
/// \ingroup core
///
/// \overview
/// The header's description above gives the usage and the rules in full.
///
/// \relations
/// - See the file description above for the related types and functions.
/// - Group: \ref core.
///
/// \impls
/// None: a single implementation.
///
/// \contracts
/// Stated in the file description above where they apply (thread safety, exceptions, lifetime); otherwise the usual value-type rules: no internal synchronisation.
///
/// \errors
/// See the `\throws` of the members; none otherwise.
///
/// \examples
/// No demo of its own; the tests show every use (tests/secret_test.cpp).
///
/// \perf
/// Not benchmarked.
///
/// \testing
/// - Tests: tests/secret_test.cpp.
/// - Demo: none of its own.
///
/// \deps
/// CMake target `snicholls::core`; standard library only (app core).
///
/// \gotchas
/// None known.
///
/// \status
/// Stable, pre-1.0.
template <typename T>
class secret
{
public:
    /// \brief The stored object type.
    using value_type = T;

    /// \brief Constructs it.
    secret() = default;
    /// \brief Constructs it.
    /// \param value the value.
    explicit secret(T value) noexcept(std::is_nothrow_move_constructible_v<T>) : value_(std::move(value)) {}

    /// \brief Constructs it.
    secret(const secret&) = default;
    /// \brief Constructs it.
    secret(secret&&) noexcept(std::is_nothrow_move_constructible_v<T>) = default;
    /// \brief Assigns.
    /// \return the result.
    secret& operator=(const secret&) = default;
    /// \brief Assigns.
    /// \return the result.
    secret& operator=(secret&&) noexcept(std::is_nothrow_move_assignable_v<T>) = default;

    /// \brief Best effort: overwrite string storage before it is released.
    ///
    /// With `secure_wipe` (`hash/secure.hpp`), whose volatile writes the optimiser may not elide.
    ~secret() { wipe(); }

    /// \brief The reveal.
    /// \return the reveal.
    [[nodiscard]] const T& reveal() const& noexcept { return value_; }
    /// \brief The reveal.
    /// \return the reveal.
    [[nodiscard]] T& reveal() & noexcept { return value_; }

    /// \brief Equality.
    /// \param l the l.
    /// \param r the r.
    /// \return the result.
    friend bool operator==(const secret& l, const secret& r) noexcept(noexcept(l.value_ == r.value_))
    {
        return l.value_ == r.value_;
    }

    /// \brief Writes the value to a stream.
    /// \param os the output stream.
    /// \return the result.
    friend std::ostream& operator<<(std::ostream& os, const secret&) { return os << masked_text; }

private:
    void wipe() noexcept
    {
        if constexpr (std::is_same_v<T, std::string>)
        {
            secure_wipe(std::span<char>(value_.data(), value_.size()));
        }
    }

    T value_{};
};

template <typename T>
struct is_secret : std::false_type {};

template <typename T>
struct is_secret<secret<T>> : std::true_type {};

/// \brief Whether the type is secret (compile-time constant).
template <typename T>
inline constexpr bool is_secret_v = is_secret<std::remove_cvref_t<T>>::value;

namespace detail {

constexpr char ascii_upper(char c) noexcept
{
    return (c >= 'a' && c <= 'z') ? static_cast<char>(c - 'a' + 'A') : c;
}

} // namespace detail

/// \brief True for configuration keys that conventionally hold secrets.
///
/// Case-insensitive. False positives are harmless (a value is masked); false negatives are not, so the list errs on the side of masking.
/// \ingroup core
/// \param key the key.
/// \return the result.
[[nodiscard]] inline bool is_secret_key(std::string_view key)
{
    std::string upper(key);
    std::transform(upper.begin(), upper.end(), upper.begin(), detail::ascii_upper);
    constexpr std::string_view markers[] = {"PASSWORD", "PASSWD", "PASSPHRASE", "SECRET", "TOKEN", "CREDENTIAL",
                                            "PRIVATE",  "AUTH",   "API_KEY",    "APIKEY", "ACCESS_KEY", "COOKIE",
                                            "SESSION",  "SIGNATURE"};
    for (const std::string_view marker : markers)
        if (upper.find(marker) != std::string::npos)
            return true;
    return upper == "KEY" || upper.ends_with("_KEY") || upper.ends_with("_PWD");
}

/// \brief "postgres://user:pw\@host/db" -> "postgres://user:********\@host/db".
///
/// Values without credentials are unchanged.
/// \ingroup core
/// \param value the value.
/// \return the result.
[[nodiscard]] inline std::string mask_url_credentials(std::string_view value)
{
    const std::size_t scheme = value.find("://");
    if (scheme == std::string_view::npos)
        return std::string(value);
    const std::size_t authority = scheme + 3;
    const std::size_t end = value.find_first_of("/?#", authority);
    const std::string_view host_part = value.substr(authority, end == std::string_view::npos ? value.npos : end - authority);
    const std::size_t at = host_part.rfind('@');
    if (at == std::string_view::npos)
        return std::string(value);
    const std::size_t colon = host_part.find(':');
    if (colon == std::string_view::npos || colon > at)
        return std::string(value);
    std::string out(value.substr(0, authority + colon + 1));
    out += masked_text;
    out += value.substr(authority + at);
    return out;
}

} // namespace snicholls

#endif /* snicholls_core_secret_hpp */
