        struct plain_chain {
            /// \brief The family. \return `Kind`.
            static constexpr chain_kind kind() noexcept { return Kind; }
            /// \brief The native asset. \return A value of its type.
            static constexpr Native native_asset() noexcept { return {}; }
        };
