/// \file
/// \brief Proleptic Gregorian calendar arithmetic on plain integers.
/// \ingroup core
///
/// Proleptic Gregorian calendar arithmetic on plain integers (Howard Hinnant, "chrono-Compatible Low-Level Date
/// Algorithms", http://howardhinnant.github.io/date_algorithms.html):
///
/// \code
///   snicholls::days_from_civil(2024, 2, 29)   == 19782        // days since 1970-01-01
///   snicholls::civil_from_days(19782)         == {2024, 2, 29}
///   snicholls::weekday_from_days(19782)       == 4             // 0 = Sunday ... 6 = Saturday (C encoding)
/// \endcode
///
/// The same algorithms std::chrono::year_month_day uses, without its range (year -32767..32767) or validity
/// checks: constexpr, noexcept, branch-light, exact for every day count |z| < 2^60 (any snicholls::utc is within
/// +-2^37 days). No validation: days_from_civil(2025, 2, 30) is 2025-03-02 - check with
/// snicholls::last_day_of_month first when the input is untrusted. Year 0 is 1 BC (ISO 8601 / astronomical).

#ifndef snicholls_core_time_civil_hpp
#define snicholls_core_time_civil_hpp

#include <cstdint>

namespace snicholls {

/// \brief A proleptic Gregorian date as plain integers (year, month, day).
/// \ingroup core
///
/// \overview
/// See the file description above.
///
/// \relations
/// - Conversions `snicholls::days_from_civil`, `snicholls::civil_from_days`; used by `snicholls::utc` text.
/// - Group: \ref core.
///
/// \impls
/// None: a single implementation.
///
/// \contracts
/// - `constexpr`, `noexcept`, O(1).
///
/// \errors
/// None.
///
/// \examples
/// \snippet civil_demo.cpp demo
///
/// \perf
/// `snicholls::civil_from_days` 8.8 ns (macOS) / 8.9 ns (Ubuntu) vs `std::year_month_day` 9.3 / 5.3 ns.
///
/// \testing
/// - Tests: tests/time/civil_test.cpp.
/// - Demo: demos/time/civil_demo.cpp.
///
/// \deps
/// CMake target `snicholls::core`; standard library only .
///
/// \gotchas
/// None known.
///
/// \status
/// Stable, pre-1.0.
struct civil_date
{
    /// \brief The year.
    std::int64_t year{1970};
    /// \brief The month.
    unsigned month{1};
    /// \brief The day.
    unsigned day{1};

    /// \brief Equality.
    /// \return the result.
    friend constexpr bool operator==(const civil_date&, const civil_date&) noexcept = default;
};

/// \brief Whether the value is leap year.
/// \param y the y.
/// \return `true` if the value is leap year.
constexpr bool is_leap_year(std::int64_t y) noexcept
{
    return y % 4 == 0 && (y % 100 != 0 || y % 400 == 0);
}

/// \brief Last day of month m (1..12) of year y: 28..31.
/// \ingroup core
/// \param y the y.
/// \param m the m.
/// \return the result.
constexpr unsigned last_day_of_month(std::int64_t y, unsigned m) noexcept
{
    return m == 2 ? (is_leap_year(y) ? 29U : 28U) : (m == 4 || m == 6 || m == 9 || m == 11) ? 30U : 31U;
}

/// \brief Days since 1970-01-01 of y-m-d (m 1..12, d 1..31; not validated).
/// \ingroup core
/// \param y the y.
/// \param m the m.
/// \param d the d.
/// \return the result.
constexpr std::int64_t days_from_civil(std::int64_t y, unsigned m, unsigned d) noexcept
{
    y -= m <= 2;
    const std::int64_t era = (y >= 0 ? y : y - 399) / 400;
    const auto yoe = static_cast<unsigned>(y - era * 400);                     // [0, 399]
    const unsigned doy = (153 * (m > 2 ? m - 3 : m + 9) + 2) / 5 + d - 1;       // [0, 365]
    const unsigned doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;                 // [0, 146096]
    return era * 146097 + static_cast<std::int64_t>(doe) - 719468;
}

/// \brief The civil date of z days since 1970-01-01.
/// \ingroup core
/// \param z the z.
/// \return the civil date of z days since 1970-01-01.
constexpr civil_date civil_from_days(std::int64_t z) noexcept
{
    z += 719468;
    const std::int64_t era = (z >= 0 ? z : z - 146096) / 146097;
    const auto doe = static_cast<unsigned>(z - era * 146097);                       // [0, 146096]
    const unsigned yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;      // [0, 399]
    const unsigned doy = doe - (365 * yoe + yoe / 4 - yoe / 100);                    // [0, 365]
    const unsigned mp = (5 * doy + 2) / 153;                                         // [0, 11]
    const unsigned d = doy - (153 * mp + 2) / 5 + 1;                                 // [1, 31]
    const unsigned m = mp < 10 ? mp + 3 : mp - 9;                                    // [1, 12]
    return {static_cast<std::int64_t>(yoe) + era * 400 + (m <= 2), m, d};
}

/// \brief civil_from_days for the years 0000..9999 only, in 32-bit unsigned arithmetic.
///
/// The same algorithm shifted by one 400-year era so nothing is negative (no era branch, no 64-bit division).
///
/// Used by the RFC 3339 formatter. Precondition: the year is in [0, 9999] (checked exhaustively in the tests). Neri-Schneider's algorithm (the one libstdc++ uses) was measured too: faster on Ubuntu/libstdc++, but 3x slower inside to_chars with AppleClang/arm64, so it is not used.
/// \ingroup core
/// \param z the z.
/// \return the result.
constexpr civil_date civil_from_days_fast(std::int64_t z) noexcept
{
    const auto u = static_cast<std::uint32_t>(z + 719468 + 146097);
    const std::uint32_t era = u / 146097;
    const std::uint32_t doe = u - era * 146097;
    const std::uint32_t yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    const std::uint32_t doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    const std::uint32_t mp = (5 * doy + 2) / 153;
    const std::uint32_t d = doy - (153 * mp + 2) / 5 + 1;
    const std::uint32_t m = mp < 10 ? mp + 3 : mp - 9;
    return {static_cast<std::int64_t>(yoe + era * 400 + (m <= 2)) - 400, m, d};
}

/// \brief Day of the week of z days since 1970-01-01 (a Thursday): 0 = Sunday ...
///
/// 6 = Saturday.
/// \ingroup core
/// \param z the z.
/// \return the result.
constexpr unsigned weekday_from_days(std::int64_t z) noexcept
{
    return static_cast<unsigned>(z >= -4 ? (z + 4) % 7 : (z + 5) % 7 + 6);
}

} // namespace snicholls

#endif /* snicholls_core_time_civil_hpp */

namespace snicholls {

/// \brief Whether the value is weekend.
/// \param wd the wd.
/// \return `true` if the value is weekend.
constexpr bool is_weekend(std::chrono::weekday wd) noexcept
{
    return wd == std::chrono::Saturday || wd == std::chrono::Sunday;
}

/// \brief Whether `d` is Monday to Friday.
/// \ingroup core
///
/// \overview
/// Weekday arithmetic on `std::chrono` calendar types: a Monday-to-Friday calendar (no holidays). See the file description above.
///
/// \relations
/// - `snicholls::add_business_days`, `snicholls::business_days_between`, `snicholls::next_weekday`, `snicholls::add_months`.
/// - Group: \ref core.
///
/// \impls
/// None: a single implementation.
///
/// \contracts
/// - O(1), `constexpr`, `noexcept`.
///
/// \errors
/// None.
///
/// \examples
/// \snippet business_days_demo.cpp demo
///
/// \perf
/// Not benchmarked.
///
/// \testing
/// - Tests: tests/time/business_days_test.cpp.
/// - Demo: demos/time/business_days_demo.cpp.
///
/// \deps
/// CMake target `snicholls::core`; standard library only .
///
/// \gotchas
/// - No holiday calendars: weekends only.
///
/// \status
/// Stable, pre-1.0.
///
/// \param d the day.
/// \return `true` for Monday to Friday.
constexpr bool is_business_day(std::chrono::sys_days d) noexcept
{
    return !is_weekend(std::chrono::weekday(d));
}

/// \brief The n-th business day after d (n > 0) or before d (n < 0).
///
/// D itself never counts and may be a weekend day.
///
/// n == 0 returns d unchanged.
/// \ingroup core
/// \param d the d.
/// \param n the count.
/// \return the n-th business day after d (n > 0) or before d (n < 0).
constexpr std::chrono::sys_days add_business_days(std::chrono::sys_days d, std::int64_t n) noexcept
{
    using std::chrono::days;
    if (n == 0) return d;
    const unsigned iso = std::chrono::weekday(d).iso_encoding();   // Monday 1 .. Sunday 7
    if (n > 0) {
        if (iso >= 6) d -= days(iso - 5);   // weekend: count from the Friday before
        const auto w = static_cast<std::int64_t>(std::chrono::weekday(d).iso_encoding() - 1);   // 0..4
        const std::int64_t rem = n % 5;
        return d + days(n / 5 * 7 + rem + (w + rem > 4 ? 2 : 0));
    }
    if (iso >= 6) d += days(8 - iso);   // weekend: count from the Monday after
    const auto w = static_cast<std::int64_t>(std::chrono::weekday(d).iso_encoding() - 1);
    const std::int64_t m = -n;
    const std::int64_t rem = m % 5;
    return d - days(m / 5 * 7 + rem + (w - rem < 0 ? 2 : 0));
}

/// \brief Business days in [a, b); negative when b < a.
///
/// business_days_between(a, add_business_days(a, n)) == n for every business day a.
/// \ingroup core
/// \param a the left operand.
/// \param b the right operand.
/// \return the result.
constexpr std::int64_t business_days_between(std::chrono::sys_days a, std::chrono::sys_days b) noexcept
{
    // f(x) = business days in [M, x) for a fixed Monday M (1970-01-05): 5 per whole week + min(rest, 5).
    constexpr std::int64_t monday = 4;
    const auto f = [](std::int64_t x) noexcept {
        const std::int64_t k = x - monday;
        const std::int64_t q = k >= 0 ? k / 7 : -((-k + 6) / 7);
        const std::int64_t r = k - q * 7;
        return q * 5 + (r < 5 ? r : 5);
    };
    return f(b.time_since_epoch().count()) - f(a.time_since_epoch().count());
}

/// \brief The latest day strictly before d that is a wd (d - 7 if d is one).
/// \ingroup core
/// \param d the d.
/// \param wd the wd.
/// \return the latest day strictly before d that is a wd (d - 7 if d is one).
constexpr std::chrono::sys_days previous_weekday(std::chrono::sys_days d, std::chrono::weekday wd) noexcept
{
    const auto back = std::chrono::weekday(d) - wd;   // [0, 6]
    return d - (back.count() == 0 ? std::chrono::days(7) : back);
}

/// \brief The earliest day strictly after d that is a wd (d + 7 if d is one).
/// \ingroup core
/// \param d the d.
/// \param wd the wd.
/// \return the earliest day strictly after d that is a wd (d + 7 if d is one).
constexpr std::chrono::sys_days next_weekday(std::chrono::sys_days d, std::chrono::weekday wd) noexcept
{
    const auto ahead = wd - std::chrono::weekday(d);   // [0, 6]
    return d + (ahead.count() == 0 ? std::chrono::days(7) : ahead);
}

/// \brief d + n months, the day clamped to the last day of the target month (Jan 31 + 1 month = Feb 28/29).
///
/// Precondition: d.ok().
/// \ingroup core
/// \param d the d.
/// \param n the count.
/// \return the result.
constexpr std::chrono::year_month_day add_months(std::chrono::year_month_day d, int n) noexcept
{
    const std::chrono::year_month ym = std::chrono::year_month(d.year(), d.month()) + std::chrono::months(n);
    const unsigned last = last_day_of_month(static_cast<int>(ym.year()), static_cast<unsigned>(ym.month()));
    const unsigned day = static_cast<unsigned>(d.day());
    return std::chrono::year_month_day(ym.year(), ym.month(), std::chrono::day(day < last ? day : last));
}

} // namespace snicholls

#endif /* snicholls_core_time_business_days_hpp */

#include <chrono>
#include <cstdint>
#include <string_view>
#include <utility>

namespace snicholls::finance {

    /// \brief How a date that is not a business day moves to one (ISDA 2006 4.12).
    /// \ingroup core
    enum class business_day_convention : std::uint8_t {
        unadjusted,           ///< the date as it is
        following,            ///< the first business day on or after
        modified_following,   ///< following, unless that is in the next month, then preceding
        preceding,            ///< the last business day on or before
        modified_preceding,   ///< preceding, unless that is in the previous month, then following
    };

    /// \brief Why an adjustment failed.
    /// \ingroup core
    enum class business_day_errc : std::uint8_t {
        no_business_day = 1,   ///< more than `max_business_day_search` closed days in a row
    };

    /// \brief The most closed days in a row an adjustment passes before it gives up: a year.
    /// \ingroup core
    inline constexpr int max_business_day_search = 366;

    /// \brief The reference calendar: Monday to Friday open, Saturday and Sunday closed, no holidays.
    /// \ingroup core
    struct weekend_calendar {
        /// \brief The calendar's name.
        /// \return `"weekends"`.
        static constexpr std::string_view name() noexcept { return "weekends"; }
        /// \brief Whether `day` is Monday to Friday.
        /// \param day The day.
        /// \return `true` for Monday to Friday.
        static constexpr bool is_business_day(std::chrono::sys_days day) noexcept { return snicholls::is_business_day(day); }
    };

    /// \brief A calendar from a holiday predicate: open Monday to Friday unless `is_holiday(day)`.
    /// \ingroup core
    /// \tparam F A callable `bool(std::chrono::sys_days)`: a lambda over the caller's set or table of holidays.
    template <typename F>
    struct weekends_and_holidays {
        F is_holiday;   ///< `true` for a weekday the market is closed

        /// \brief Whether `day` is a weekday and not a holiday.
        /// \param day The day.
        /// \return `true` when the market is open.
        constexpr bool is_business_day(std::chrono::sys_days day) const noexcept(noexcept(static_cast<bool>(is_holiday(day))))
        {
            return snicholls::is_business_day(day) && !static_cast<bool>(is_holiday(day));
        }
    };

    /// \brief Deduce the predicate's type: `weekends_and_holidays{[&](auto d) { return set.contains(d); }}`.
    template <typename F>
    weekends_and_holidays(F) -> weekends_and_holidays<F>;

    namespace detail {
        // The first business day at or after `day` stepping by `step` (+1 or -1) days, within the search limit.
        template <typename C>
        constexpr result<std::chrono::sys_days, business_day_errc> roll(std::chrono::sys_days day, int step, const C& calendar)
        {
            for (int i = 0; i <= max_business_day_search; ++i, day += std::chrono::days(step))
                if (static_cast<bool>(calendar.is_business_day(day)))
                    return ok(day);
            return err(business_day_errc::no_business_day);
        }

        constexpr std::chrono::month month_of(std::chrono::sys_days day) noexcept
        {
            return std::chrono::year_month_day(day).month();
        }

        // Roll by `step`; if that leaves the month, roll the other way.
        template <typename C>
        constexpr result<std::chrono::sys_days, business_day_errc> roll_modified(std::chrono::sys_days day, int step, const C& calendar)
        {
            const auto r = roll(day, step, calendar);
            if (r && month_of(*r) != month_of(day))
                return roll(day, -step, calendar);
            return r;
        }
    } // namespace detail

    /// \brief Move `day` to a business day of `calendar` by `convention`.
    /// \ingroup core
    /// \tparam C A `holiday_calendar`.
    /// \param day        The date.
    /// \param convention The rule.
    /// \param calendar   The calendar.
    /// \return The adjusted date (`day` itself when it is a business day or the rule is `unadjusted`), or
    /// `no_business_day`.
    template <holiday_calendar C>
    [[nodiscard]] constexpr result<std::chrono::sys_days, business_day_errc>
    adjust(std::chrono::sys_days day, business_day_convention convention, const C& calendar) noexcept(noexcept(calendar.is_business_day(day)))
    {
        switch (convention) {
        case business_day_convention::following: return detail::roll(day, 1, calendar);
        case business_day_convention::modified_following: return detail::roll_modified(day, 1, calendar);
        case business_day_convention::preceding: return detail::roll(day, -1, calendar);
        case business_day_convention::modified_preceding: return detail::roll_modified(day, -1, calendar);
        case business_day_convention::unadjusted: break;
        }
        return ok(day);
    }

    static_assert(holiday_calendar<weekend_calendar>, "snicholls::finance::weekend_calendar must model snicholls::holiday_calendar");

} // namespace snicholls::finance

#endif // snicholls_core_finance_business_day_hpp
