namespace detail::iq_grids
{
    // Each point's coordinates as bytes: level l of coordinate k becomes levels[l] in byte k
    template <typename Word, std::size_t N, std::size_t Levels>
    consteval std::array<Word, N> expand(const std::array<std::uint16_t, N>& index, int bits, int dims,
                                         const std::array<std::uint8_t, Levels>& levels)
    {
        std::array<Word, N> grid{};
        for (std::size_t g = 0; g < N; ++g) {
            Word w = 0;
            for (int k = 0; k < dims; ++k)
                w |= Word(levels[(index[g] >> (bits * k)) & ((1u << bits) - 1)]) << (8 * k);
            grid[g] = w;
        }
        return grid;
    }

    template <std::size_t N>
    consteval bool ascending(const std::array<std::uint16_t, N>& a)
    {
        for (std::size_t i = 1; i < N; ++i)
            if (!(a[i - 1] < a[i]))
                return false;
        return true;
    }

    inline constexpr std::array<std::uint8_t, 3> iq2_levels{0x08, 0x19, 0x2b};
    inline constexpr std::array<std::uint8_t, 3> iq1_levels{0xff, 0x00, 0x01};
    inline constexpr std::array<std::uint8_t, 8> iq3xxs_levels{0x04, 0x0c, 0x14, 0x1c, 0x24, 0x2c, 0x34, 0x3e};
    inline constexpr std::array<std::uint8_t, 8> iq3s_levels{0x01, 0x03, 0x05, 0x07, 0x09, 0x0b, 0x0d, 0x0f};

    consteval std::array<std::uint8_t, 128> signs()
    {
        std::array<std::uint8_t, 128> s{};
        for (unsigned i = 0; i < 128; ++i) {
            unsigned parity = 0;
            for (unsigned b = 0; b < 7; ++b)
                parity ^= (i >> b) & 1u;
            s[i] = static_cast<std::uint8_t>(i | (parity << 7));
        }
        return s;
    }
} // namespace detail::iq_grids

static_assert(detail::iq_grids::ascending(iq2xxs_grid_index) && detail::iq_grids::ascending(iq2xs_grid_index)
                  && detail::iq_grids::ascending(iq2s_grid_index) && detail::iq_grids::ascending(iq1s_grid_index)
                  && detail::iq_grids::ascending(iq3xxs_grid_index) && detail::iq_grids::ascending(iq3s_grid_index),
              "snicholls::ml: the IQ grid index lists must be ascending, for iq_grid_find");

